// KT1 Host: a column row's compared values to the check helper (Host/Check.h).
// KT1_SCAFFOLD generated by game-build tools/engine/kt1_scaffold.py. Do not edit.
//
// The Lua twin answers under the same keys: Spring.KT1.Check.Answer(system, column, id, index, count, value)
//   a single value      index 0, count 0
//   an array of three   index 0 to 2, count 0
//   a list              first (id, 0, 1) with its length, then (id, index, 0) per element
// Integers go as floats: exact below two to the power 24 (unit ids and steps are).

#ifndef KT1_HOST_CHECK_COLUMNS_H
#define KT1_HOST_CHECK_COLUMNS_H

#include <array>
#include <cstddef>
#include <cstdint>
#include <vector>

#include "Game/KT1/Host/Check.h"

namespace KT1 {

struct CheckColumns {
	const char* system;
	int id;

	void operator()(const char* column, const bool& v, bool compare) const {
		if (compare) Give(column, 0, 0, static_cast<float>(v));
	}
	void operator()(const char* column, const uint8_t& v, bool compare) const {
		if (compare) Give(column, 0, 0, static_cast<float>(v));
	}
	void operator()(const char* column, const uint16_t& v, bool compare) const {
		if (compare) Give(column, 0, 0, static_cast<float>(v));
	}
	void operator()(const char* column, const int32_t& v, bool compare) const {
		if (compare) Give(column, 0, 0, static_cast<float>(v));
	}
	void operator()(const char* column, const float& v, bool compare) const {
		if (compare) Give(column, 0, 0, static_cast<float>(v));
	}
	template<std::size_t N> void operator()(const char* column, const std::array<float, N>& v, bool compare) const {
		if (!compare) return;
		for (std::size_t i = 0; i < N; ++i) Give(column, static_cast<int>(i), 0, v[i]);
	}
	template<class T> void operator()(const char* column, const std::vector<T>& v, bool compare) const {
		if (!compare) return;
		Give(column, 0, 1, static_cast<float>(v.size()));
		for (std::size_t i = 0; i < v.size(); ++i) Give(column, static_cast<int>(i), 0, static_cast<float>(v[i]));
	}

private:
	void Give(const char* column, int index, int count, float value) const {
		Check::Native(system, column, id, index, count, value);
	}
};

} // namespace KT1

#endif
